                                    { id: 'Team challenges', title: 'Squad Leader', desc: 'I thrive when collaborating and leading groups.', icon: <Users /> },
                                    { id: 'Solo focus', title: 'Lone Wolves', desc: 'I do my best work with deep, uninterrupted focus.', icon: <Target /> },
