                            <button
                                onClick={() => { handleModeSwitch('client'); setMobileMenuOpen(false); }}
                                className={`py-3 rounded-lg font-bold text-center ${viewMode === 'client' ? 'bg-purple-500 text-white' : 'text-slate-400'}`}
