                                className="h-full bg-cyan-400"
                            />
                        </div>
                    </div>
                )}

                {stage === "RESULT" && (
                    <motion.div
                        initial={{ scale: 0.9, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        className="bg-zinc-900/80 border border-white/10 p-8 rounded-3xl w-full max-w-lg backdrop-blur-md"
