                                <div className="bg-zinc-900 px-4 py-2 border-b border-white/10 flex items-center justify-between">
                                    <span className="text-xs font-mono text-zinc-500">editor.main</span>
                                    <span className="text-xs font-mono text-green-500">ONLINE</span>
                                </div>

                                <textarea
                                    value={content}
                                    onChange={(e) => { setContent(e.target.value); setFeedback(null); }}
                                    className="flex-1 bg-transparent p-6 text-zinc-300 font-mono focus:outline-none resize-none text-lg leading-relaxed"
                                    placeholder="// Begin your work here..."
                                    spellCheck="false"
                                />

                                {feedback && (
                                    <div className="absolute bottom-24 left-6 right-6 bg-amber-900/95 border border-amber-500/50 text-white p-4 rounded-xl backdrop-blur-md shadow-xl animate-bounce-in">
                                        <div className="flex items-center gap-3">
                                            <span className="text-2xl">💡</span>
                                            <div><h4 className="font-bold text-amber-300 text-xs uppercase">Coach's Tip</h4><p className="text-sm">{feedback}</p></div>
                                        </div>
                                    </div>
                                )}

                                <div className="p-4 border-t border-white/10 bg-zinc-900/50 space-y-3">
                                    <div className="flex items-center gap-3">
                                        <div className="flex-1 h-2 bg-zinc-800 rounded-full overflow-hidden">
                                            <div className={`h-full ${scoreInfo.color} transition-all duration-300`} style={{ width: `${liveScore}%` }} />
                                        </div>
                                        <span className={`text-xs font-mono ${scoreInfo.textColor} min-w-[80px] text-right`}>{scoreInfo.label}</span>
                                    </div>
                                    <div className="flex justify-end">
                                        <button onClick={handleSubmit} disabled={isSubmitting || !content.trim()} className={`px-8 py-3 rounded-xl font-bold uppercase tracking-widest transition-all ${content.trim() ? "bg-green-500 text-black hover:bg-green-400 hover:scale-105" : "bg-zinc-800 text-zinc-500 cursor-not-allowed"}`}>
                                            {isSubmitting ? "Analyzing..." : "Submit Work"}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, useMemo, useEffect } from 'react';
import { KNOWLEDGE_BASE, type SkillNode } from '../data/KnowledgeBase';
import { Neo4jService } from '../services/Neo4jService';
import type { ReactNode } from 'react';

// ----------------- TYPES -----------------
export interface UserProfile {
    name: string;
    age: number; // Mapping grade to age approx or using grade
    passion: string;
    style: string;
}

export interface HeroPath {
    role: string;
    currentMission: string | null;
    currentMissionId: string | null;
    status: "Idle" | "Active" | "Completed";
    level: number;
    xp: number;
    history: string[];
}

export interface Wallet {
    balance: number;
}

export interface Squad {
    id: string;
    name: string;
    role: string;
}

export interface Psychometrics {
    autonomy: number;
    competence: number;
    relatedness: number;
}

interface UserContextType {
    userProfile: UserProfile | null;
    heroPath: HeroPath | null;
    wallet: Wallet;
    squad: Squad | null;
    knowledge: SkillNode[];
    synapseCount: number;
    psychometrics: Psychometrics;
    interventions: any[];
    setUser: (profile: UserProfile, path: HeroPath) => void;
    setHeroPath: React.Dispatch<React.SetStateAction<HeroPath | null>>;
    updateXP: (amount: number) => void;
    addBalance: (amount: number) => void;
    completeMission: (xpReward: number, balanceReward: number) => void;
    joinSquad: (squad: Squad) => void;
    updateMastery: (nodeId: string, correct: boolean) => void;
    updatePsychometrics: (vector: keyof Psychometrics, amount: number) => void;
    isInitialized: boolean;
}

// ----------------- CONTEXT -----------------
const UserContext = createContext<UserContextType | undefined>(undefined);

export const UserProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [heroPath, setHeroPath] = useState<HeroPath | null>(null);
    const [wallet, setWallet] = useState<Wallet>({ balance: 0 });
    const [squad, setSquad] = useState<Squad | null>(null);
    const [knowledge, setKnowledge] = useState<SkillNode[]>(KNOWLEDGE_BASE);
    const [psychometrics, setPsychometrics] = useState<Psychometrics>({
        autonomy: 10,
        competence: 10,
        relatedness: 10
    });
    const [interventions, setInterventions] = useState<any[]>([]);

    const synapseCount = useMemo(() => {
        return knowledge.reduce((sum, node) => sum + node.mastery, 0);
    }, [knowledge]);

    const isInitialized = !!userProfile && !!heroPath;

    // Load data from Neo4j on mount
    useEffect(() => {
        const loadSovereignData = async () => {
            const savedId = localStorage.getItem('mbp_sovereign_id');
            const databaseOnline = Neo4jService.isHealthy();

            if (savedId && databaseOnline) {
                const data = await Neo4jService.fetchUserData(savedId);
                if (data) {
                    setUserProfile(data.profile);
                    setHeroPath(data.path);
                    setWallet(data.wallet);
                    setPsychometrics(data.psychometrics);
                    setSquad(data.squad);

                    const recommendations = await Neo4jService.fetchRecommendations(savedId);
                    setInterventions(recommendations);
                    return; // Loaded from DB
                }
            }

            // SOVEREIGN FALLBACK: If no DB or no ID, load a "Guest Legend" for showcase
            console.log("🚀 Sovereign Fallback: Loading Guest Legend Profile for Showcase");
            setUserProfile({
                name: "Guest Legend",
                age: 18,
                passion: "Impact Innovation",
                style: "Architect"
            });
            setHeroPath({
                role: "Founding Solver",
                currentMission: null,
                currentMissionId: null,
                status: "Idle",
                level: 3,
                xp: 2450,
                history: []
            });
            setWallet({ balance: 500 });
            setPsychometrics({
                autonomy: 65,
                competence: 80,
                relatedness: 45
            });
            setSquad({
                id: 'squad-1',
                name: 'The Ocean Cleanup Crew',
                role: 'Coder'
            });
        };
        loadSovereignData();
    }, []);

    const setUser = async (profile: UserProfile, path: HeroPath) => {
        const userId = `sovereign_${profile.name.toLowerCase().replace(/\s+/g, '_')}`;
        localStorage.setItem('mbp_sovereign_id', userId);

        setUserProfile(profile);
        setHeroPath(path);

        // Initial sync to Neo4j
        await Neo4jService.saveUserProfile(userId, profile, path, wallet, psychometrics);
    };

    const updateXP = (amount: number) => {
        if (!heroPath) return;
        const newXP = heroPath.xp + amount;
        const newLevel = Math.floor(newXP / 1000) + 1; // Simple level logic
        setHeroPath({ ...heroPath, xp: newXP, level: newLevel });
    };

    const addBalance = (amount: number) => {
        setWallet(prev => ({ balance: prev.balance + amount }));
    };

    const completeMission = async (xpReward: number, balanceReward: number) => {
        if (!heroPath || !userProfile) return;

        const newXP = heroPath.xp + xpReward;
        const newLevel = Math.floor(newXP / 1000) + 1;
        const completedId = heroPath.currentMissionId;
        const newHistory = completedId ? [...heroPath.history, completedId] : heroPath.history;

        const updatedPath: HeroPath = {
            ...heroPath,
            currentMission: null,
            currentMissionId: null,
            status: "Idle" as const,
            xp: newXP,
            level: newLevel,
            history: newHistory
        };

        const updatedWallet: Wallet = { balance: wallet.balance + balanceReward };

        setHeroPath(updatedPath);
        setWallet(updatedWallet);

        // Sync to Neo4j
        const userId = localStorage.getItem('mbp_sovereign_id');
        if (userId && completedId) {
            await Neo4jService.completeMission(userId, completedId, updatedPath, updatedWallet);
        }
    };

    const joinSquad = async (newSquad: Squad) => {
        setSquad(newSquad);
        const userId = localStorage.getItem('mbp_sovereign_id');
        if (userId) {
            await Neo4jService.joinSquad(userId, newSquad);
        }
    };

    const updateMastery = (nodeId: string, correct: boolean) => {
        setKnowledge(prev => prev.map(node => {
            if (node.id === nodeId) {
                const newMastery = correct
                    ? Math.min(100, node.mastery + 20)
                    : 0;
                return { ...node, mastery: newMastery };
            }
            return node;
        }));

        if (correct) {
            updatePsychometrics('competence', 5);
        }
    };

    const updatePsychometrics = async (vector: keyof Psychometrics, amount: number) => {
        const newPsychometrics = {
            ...psychometrics,
            [vector]: Math.min(100, psychometrics[vector] + amount)
        };
        setPsychometrics(newPsychometrics);

        const userId = localStorage.getItem('mbp_sovereign_id');
        if (userId) {
            await Neo4jService.updatePsychometrics(userId, newPsychometrics);
        }
    };

    return (
        <UserContext.Provider value={{
            userProfile,
            heroPath,
            wallet,
            squad,
            knowledge,
            synapseCount,
            psychometrics,
            interventions,
            setUser,
            setHeroPath,
            updateXP,
            addBalance,
            completeMission,
            joinSquad,
            updateMastery,
            updatePsychometrics,
            isInitialized
        }}>
            {children}
        </UserContext.Provider>
    );
};

// ----------------- HOOK -----------------
export const useUser = () => {
    const context = useContext(UserContext);
    if (context === undefined) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

